def can_make_square(grid):
    # Check all four possible 2x2 squares in a 3x3 grid
    for r in range(2):
        for c in range(2):
            count_B = 0
            # Sum the number of 'B' in the current 2x2 block
            for i in range(2):
                for j in range(2):
                    if grid[r + i][c + j] == 'B':
                        count_B += 1
            # If the block already has 0,1,3, or 4 'B's,
            # then it is either already uniform or can be made uniform
            # by flipping at most one cell.
            if count_B != 2:
                return True
    return False

