def isValid(word: str) -> bool:
    # Check length condition
    if len(word) < 3:
        return False

    # Define vowel set
    vowels = set('aeiouAEIOU')
    has_vowel = False
    has_consonant = False

    # Iterate over each character
    for ch in word:
        # Check if character is alphanumeric (digit or English letter)
        if not ch.isalnum():
            return False

        # If it's a letter, classify as vowel or consonant
        if ch.isalpha():
            if ch in vowels:
                has_vowel = True
            else:
                has_consonant = True

    # Both vowel and consonant must be present
    return has_vowel and has_consonant
