def maximumTime(s: str) -> str:
    # Convert string to list for easier manipulation
    time_list = list(s)

    # Process hours (positions 0 and 1)
    if time_list[0] == '?':
        if time_list[1] == '?' or int(time_list[1]) < 2:
            time_list[0] = '1'  # If second digit is unknown or 0/1, we can use 1 (10 or 11)
        else:
            time_list[0] = '0'  # If second digit is 2-9, we must use 0 (02-09)

    if time_list[1] == '?':
        if time_list[0] == '1':
            time_list[1] = '1'  # If first digit is 1, max second digit is 1 (11)
        else:  # time_list[0] is '0'
            time_list[1] = '9'  # If first digit is 0, max second digit is 9 (09)

    # Process minutes (positions 3 and 4)
    if time_list[3] == '?':
        time_list[3] = '5'  # Max tens digit for minutes is 5

    if time_list[4] == '?':
        time_list[4] = '9'  # Max ones digit for minutes is 9

    return ''.join(time_list)
