import sys
import collections

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    H = int(data[0])
    W = int(data[1])
    grid = data[2:2+H]

    # free[i][j] is True if cell (i,j) is empty and has no magnet adjacent
    free = [[False] * W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                # check four neighbours
                ok = True
                if i > 0 and grid[i-1][j] == '#':
                    ok = False
                if i < H-1 and grid[i+1][j] == '#':
                    ok = False
                if j > 0 and grid[i][j-1] == '#':
                    ok = False
                if j < W-1 and grid[i][j+1] == '#':
                    ok = False
                free[i][j] = ok

    visited_free = [[False] * W for _ in range(H)]
    # comp_id marks which component has already counted a non‑free empty cell
    comp_id = [[0] * W for _ in range(H)]
    max_ans = 1  # at least one empty cell exists, degree at least 1
    current_comp = 1

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and free[i][j] and not visited_free[i][j]:
                # BFS over free cells connected by adjacency
                q = collections.deque()
                q.append((i, j))
                visited_free[i][j] = True
                component = []
                while q:
                    x, y = q.popleft()
                    component.append((x, y))
                    for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if grid[nx][ny] == '.' and free[nx][ny] and not visited_free[nx][ny]:
                                visited_free[nx][ny] = True
                                q.append((nx, ny))

                # compute total reachable cells for this component
                size = len(component)
                extra = 0
                for x, y in component:
                    for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < H and 0 <= ny < W:
                            # non‑free empty cell not yet counted for this component
                            if grid[nx][ny] == '.' and not free[nx][ny] and comp_id[nx][ny] != current_comp:
                                comp_id[nx][ny] = current_comp
                                extra += 1
                total = size + extra
                if total > max_ans:
                    max_ans = total
                current_comp += 1

    print(max_ans)

if __name__ == "__main__":
    solve()
```

