from functools import lru_cache

def beautifulNumbers(low: int, high: int, k: int) -> int:
    def count_upto(n: int) -> int:
        if n <= 0:
            return 0
        s = str(n)
        digits = [int(c) for c in s]
        L = len(digits)

        @lru_cache(None)
        def dp(pos: int, tight: bool, started: bool, diff: int, mod: int) -> int:
            if pos == L:
                return 1 if started and diff == 0 and mod == 0 else 0
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_started = started or (d != 0)
                if new_started:
                    new_diff = diff + (1 if d % 2 == 0 else -1)
                    new_mod = (mod * 10 + d) % k
                else:
                    # still leading zeros, keep diff and mod as 0
                    new_diff = 0
                    new_mod = 0
                total += dp(pos + 1, new_tight, new_started, new_diff, new_mod)
            return total

        return dp(0, True, False, 0, 0)

    return count_upto(high) - count_upto(low - 1)
