def min_partitions(s: str) -> int:
    n = len(s)
    # dp[i] represents the minimum number of balanced substrings for s[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # Base case: empty string requires 0 partitions

    for i in range(1, n + 1):
        # Try all possible starting positions for the last substring
        for j in range(i):
            # Check if s[j:i] is balanced
            substring = s[j:i]
            freq = {}
            for char in substring:
                freq[char] = freq.get(char, 0) + 1

            # Check if all characters have the same frequency
            freq_values = list(freq.values())
            if len(freq_values) == 0:
                is_balanced = True
            else:
                is_balanced = all(f == freq_values[0] for f in freq_values)

            if is_balanced and dp[j] != float('inf'):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]
