def minimum_changes(s: str, k: int) -> int:
    n = len(s)

    # Precompute cost[i][j]: minimum changes to make s[i:j+1] a semi-palindrome
    cost = [[float('inf')] * n for _ in range(n)]

    # Helper function to compute cost for a specific substring to become semi-palindrome with period d
    def compute_cost_for_period(substring, d):
        length = len(substring)
        changes = 0
        # For each residue class modulo d, collect characters and make them palindrome
        for r in range(d):
            chars = []
            for i in range(r, length, d):
                chars.append(substring[i])
            # Make this sequence a palindrome
            for i in range(len(chars) // 2):
                if chars[i] != chars[-(i+1)]:
                    changes += 1
        return changes

    # For each possible substring s[i:j+1], compute minimum cost to make it semi-palindrome
    for i in range(n):
        for j in range(i, n):
            length = j - i + 1
            # Find all possible periods d where 1 <= d < length and length % d == 0
            for d in range(1, length):
                if length % d == 0:
                    substring = s[i:j+1]
                    changes = compute_cost_for_period(substring, d)
                    cost[i][j] = min(cost[i][j], changes)

    # DP: dp[i][p] = minimum changes to partition s[:i] into p substrings
    # Initialize with infinity
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    # Fill DP table
    for i in range(1, n + 1):
        for p in range(1, min(k, i) + 1):
            # Try all possible last substring ending at i-1
            for last_start in range(p - 1, i):
                if dp[last_start][p - 1] != float('inf'):
                    dp[i][p] = min(dp[i][p], dp[last_start][p - 1] + cost[last_start][i - 1])

    return dp[n][k]
```

