def string_matching(wordsContainer, wordsQuery):
    # Build a trie for reversed words
    # Each node stores: best_index (index of best word ending at this node), 
    #                   best_length (length of that word), 
    #                   best_prefix_length (length of common suffix with the query up to this point)
    # But actually, we'll just store at each node the best word index according to the criteria

    # Create trie node structure
    trie = {}

    # For each word in wordsContainer, we'll insert its reversed version into the trie
    # and keep track of the best candidate at each node (for suffix matching)

    for idx, word in enumerate(wordsContainer):
        reversed_word = word[::-1]
        node = trie

        # Update the root node with the best word (for empty suffix case)
        # We'll update at each node as we go down

        # Initialize best for this word at root if better than current
        if 'best' not in node:
            node['best'] = (idx, len(word))
        else:
            curr_idx, curr_len = node['best']
            # Update if current word is shorter, or same length but earlier
            if len(word) < curr_len or (len(word) == curr_len and idx < curr_idx):
                node['best'] = (idx, len(word))

        # Traverse the trie
        for char in reversed_word:
            if char not in node:
                node[char] = {}
            node = node[char]

            # Update the best candidate at this node
            if 'best' not in node:
                node['best'] = (idx, len(word))
            else:
                curr_idx, curr_len = node['best']
                # Update if current word is shorter, or same length but earlier
                if len(word) < curr_len or (len(word) == curr_len and idx < curr_idx):
                    node['best'] = (idx, len(word))

    # Now process each query
    ans = []

    for query in wordsQuery:
        reversed_query = query[::-1]
        node = trie
        best_idx = -1
        best_len = float('inf')

        # Check root first (for empty suffix case)
        if 'best' in node:
            best_idx, best_len = node['best']

        # Traverse the trie with reversed query
        for char in reversed_query:
            if char in node:
                node = node[char]
                # Update best answer with candidate at this node
                if 'best' in node:
                    curr_idx, curr_len = node['best']
                    if curr_len < best_len or (curr_len == best_len and curr_idx < best_idx):
                        best_idx, best_len = curr_idx, curr_len
            else:
                break

        ans.append(best_idx)

    return ans
