import sys

def can_be_equal(T_prime: str, S: str) -> bool:
    """Return True if S can be transformed to T_prime by at most one edit."""
    len_t = len(T_prime)
    len_s = len(S)

    # length difference must be -1, 0, or 1
    if abs(len_t - len_s) > 1:
        return False

    # equal length: check if at most one character differs
    if len_t == len_s:
        diff = 0
        for a, b in zip(T_prime, S):
            if a != b:
                diff += 1
                if diff > 1:
                    return False
        return True

    # T_prime longer by 1 -> S must be T_prime with one deletion
    if len_t == len_s + 1:
        i = j = 0
        skipped = False
        while i < len_t and j < len_s:
            if T_prime[i] == S[j]:
                i += 1
                j += 1
            else:
                if skipped:
                    return False
                skipped = True
                i += 1
        if j == len_s:
            if not skipped:
                return i == len_t - 1   # one character left to delete
            else:
                return i == len_t       # exactly matched after deletion
        return False

    # T_prime shorter by 1 -> S must be T_prime with one insertion
    # i.e., T_prime is S with one deletion
    i = j = 0
    skipped = False
    while i < len_s and j < len_t:
        if S[i] == T_prime[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            i += 1
    if j == len_t:
        if not skipped:
            return i == len_s - 1
        else:
            return i == len_s
    return False


