def punishment_number(n):
    def can_partition(num_str, target):
        # Recursive function to check if we can partition num_str into parts that sum to target
        def backtrack(pos, current_sum):
            if pos == len(num_str):
                return current_sum == target

            for end in range(pos + 1, len(num_str) + 1):
                part = int(num_str[pos:end])
                # Early termination if current sum exceeds target
                if current_sum + part > target:
                    break
                if backtrack(end, current_sum + part):
                    return True
            return False

        return backtrack(0, 0)

    total = 0
    for i in range(1, n + 1):
        square = i * i
        if can_partition(str(square), i):
            total += square
    return total
