def minimumCost(source, target, original, changed, cost):
    # Create adjacency list for the graph of character transformations
    # There are 26 lowercase English letters, so we use 26x26 matrix
    INF = float('inf')
    dist = [[INF] * 26 for _ in range(26)]

    # Initialize diagonal (distance from char to itself is 0)
    for i in range(26):
        dist[i][i] = 0

    # Add edges from the transformation rules
    for o, c, c_cost in zip(original, changed, cost):
        from_char = ord(o) - ord('a')
        to_char = ord(c) - ord('a')
        # Keep the minimum cost if there are multiple edges between same pair
        dist[from_char][to_char] = min(dist[from_char][to_char], c_cost)

    # Floyd-Warshall algorithm to find shortest paths between all pairs
    for k in range(26):
        for i in range(26):
            if dist[i][k] == INF:
                continue
            for j in range(26):
                if dist[k][j] != INF:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Calculate total cost to convert source to target
    total_cost = 0
    for s_char, t_char in zip(source, target):
        s_idx = ord(s_char) - ord('a')
        t_idx = ord(t_char) - ord('a')
        if dist[s_idx][t_idx] == INF:
            return -1
        total_cost += dist[s_idx][t_idx]

    return total_cost
