from collections import deque

def solve() -> None:
    data = sys.stdin.read().split()
    it = iter(data)
    N = int(next(it))

    # prerequisite lists: book i requires books in prereq[i]
    prereq = [[] for _ in range(N + 1)]
    # reverse: which books depend on book p
    dependents = [[] for _ in range(N + 1)]

    for i in range(1, N + 1):
        Ci = int(next(it))
        for _ in range(Ci):
            p = int(next(it))
            prereq[i].append(p)
            dependents[p].append(i)

    # Step 1: find all books that must be read to read book 1
    visited = [False] * (N + 1)
    stack = [1]
    visited[1] = True
    while stack:
        node = stack.pop()
        for p in prereq[node]:
            if not visited[p]:
                visited[p] = True
                stack.append(p)

    # Step 2: compute indegree of each node within the subgraph
    indeg = [0] * (N + 1)
    for i in range(1, N + 1):
        if visited[i]:
            cnt = 0
            for p in prereq[i]:
                if visited[p]:
                    cnt += 1
            indeg[i] = cnt

    # Step 3: Kahn's algorithm for topological order (excluding book 1)
    q = deque()
    for i in range(1, N + 1):
        if visited[i] and indeg[i] == 0 and i != 1:
            q.append(i)

    order = []
    while q:
        node = q.popleft()
        order.append(str(node))
        for dep in dependents[node]:
            if visited[dep]:
                indeg[dep] -= 1
                if indeg[dep] == 0 and dep != 1:
                    q.append(dep)

    # Output
    print(" ".join(order))

if __name__ == "__main__":
    solve()
