import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        print("No")
        return

    # Parse input
    it = iter(data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))

    tiles = []
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        tiles.append((a, b))

    total_area = H * W

    # Try all possible subsets of tiles (including none) and check if any subset can cover the grid exactly
    # Since N <= 7, we can try all 2^N subsets

    # Precompute all possible orientations for each tile
    tile_orientations = []
    for i, (a, b) in enumerate(tiles):
        # Each tile can be placed as a x b or b x a (rotated/flipped)
        # But we need to be careful with squares (a == b)
        if a == b:
            tile_orientations.append([(a, b)])
        else:
            tile_orientations.append([(a, b), (b, a)])

    # Generate all subsets of tiles
    for mask in range(1 << N):
        if mask == 0:
            # Empty set can only cover 0 area, so skip unless H*W == 0 (but constraints say H,W >= 1)
            continue

        # Get the subset of tiles
        subset = []
        for i in range(N):
            if mask & (1 << i):
                subset.append(i)

        # Calculate total area of the subset
        total_subset_area = 0
        for i in subset:
            a, b = tiles[i]
            total_subset_area += a * b

        # If total area doesn't match, skip
        if total_subset_area != total_area:
            continue

        # Now check if the subset can tile the grid
        # Since grid is small (max 10x10 = 100 cells), we can use backtracking

        # Create grid representation: grid[r][c] = True if covered, False otherwise
        grid = [[False] * W for _ in range(H)]

        # Recursive function to try placing tiles
        def backtrack(idx, tiles_list):
            if idx == len(tiles_list):
                # Check if all cells are covered
                for r in range(H):
                    for c in range(W):
                        if not grid[r][c]:
                            return False
                return True

            # Find first uncovered cell
            start_r, start_c = -1, -1
            for r in range(H):
                for c in range(W):
                    if not grid[r][c]:
                        start_r, start_c = r, c
                        break
                if start_r != -1:
                    break

            if start_r == -1:
                return True

            tile_i = tiles_list[idx]
            orientations = tile_orientations[tile_i]

            for h, w in orientations:
                # Check if tile fits at (start_r, start_c)
                if start_r + h <= H and start_c + w <= W:
                    # Check if area is free
                    can_place = True
                    for dr in range(h):
                        for dc in range(w):
                            if grid[start_r + dr][start_c + dc]:
                                can_place = False
                                break
                        if not can_place:
                            break

                    if can_place:
                        # Place the tile
                        for dr in range(h):
                            for dc in range(w):
                                grid[start_r + dr][start_c + dc] = True

                        if backtrack(idx + 1, tiles_list):
                            return True

                        # Remove the tile
                        for dr in range(h):
                            for dc in range(w):
                                grid[start_r + dr][start_c + dc] = False

            return False

        if backtrack(0, subset):
            print("Yes")
            return

    print("No")

solve()
