def canSplit(nums, m):
    n = len(nums)
    if n == 1:
        return True
    # prefix sums for O(1) range sum queries
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]
    def range_sum(l, r):
        return prefix[r + 1] - prefix[l]
    # dp[l][r] = True if interval [l, r] can be completely split into singletons
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    # iterate over intervals of increasing length
    for length in range(2, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            for k in range(l, r):
                # check condition for the two subarrays resulting from splitting at k
                left_len = k - l + 1
                right_len = r - k
                left_ok = (left_len == 1) or (range_sum(l, k) >= m)
                right_ok = (right_len == 1) or (range_sum(k + 1, r) >= m)
                if left_ok and right_ok and dp[l][k] and dp[k + 1][r]:
                    dp[l][r] = True
                    break
    return dp[0][n - 1]
