def canTraverseAllPairs(nums):
    n = len(nums)

    # Special cases
    if n == 1:
        return True
    if any(num == 1 for num in nums):
        return False

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1

    # For each number, factorize it and union indices that share a prime factor
    prime_to_indices = {}

    for i, num in enumerate(nums):
        # Get prime factors of num
        d = 2
        while d * d <= num:
            if num % d == 0:
                if d not in prime_to_indices:
                    prime_to_indices[d] = []
                prime_to_indices[d].append(i)
                while num % d == 0:
                    num //= d
            d += 1
        # If num is a prime greater than 1
        if num > 1:
            if num not in prime_to_indices:
                prime_to_indices[num] = []
            prime_to_indices[num].append(i)

    # Union indices that share the same prime factor
    for primes in prime_to_indices.values():
        for i in range(1, len(primes)):
            union(primes[0], primes[i])

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
