def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    # adjacency matrix: adj[i][j] == True if nums[i] and nums[j] divide each other
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                adj[i][j] = True

    # dp[mask][last] = number of ways to get mask with last index 'last'
    dp = [[0] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = 1

    # iterate over all masks
    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            cur = dp[mask][last]
            if cur == 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if adj[last][nxt]:
                    new_mask = mask | (1 << nxt)
                    dp[new_mask][nxt] = (dp[new_mask][nxt] + cur) % MOD

    full_mask = (1 << n) - 1
    ans = 0
    for i in range(n):
        ans = (ans + dp[full_mask][i]) % MOD
    return ans
