def maximumSubarraySum(nums, k):
    n = len(nums)
    # Prefix sum array: prefix[i] = sum of nums[0..i-1]
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # Dictionary to store minimum prefix sum for each value encountered
    # key: nums[i], value: minimum prefix[i] (sum before index i)
    min_prefix = {}
    max_sum = None  # Track maximum sum, None if no good subarray found yet

    for j in range(n):
        # Check for possible starting elements: nums[i] such that |nums[i] - nums[j]| == k
        # So nums[i] = nums[j] + k or nums[i] = nums[j] - k
        for target in (nums[j] + k, nums[j] - k):
            if target in min_prefix:
                # Subarray from index i+1 to j has sum = prefix[j+1] - prefix[i+1]
                # But min_prefix[target] stores prefix[i], so sum = prefix[j+1] - min_prefix[target]
                current_sum = prefix[j + 1] - min_prefix[target]
                if max_sum is None or current_sum > max_sum:
                    max_sum = current_sum

        # Update min_prefix for current nums[j] value
        # We want the minimum prefix[i] for each nums[i] to maximize subarray sum
        if nums[j] in min_prefix:
            if prefix[j] < min_prefix[nums[j]]:
                min_prefix[nums[j]] = prefix[j]
        else:
            min_prefix[nums[j]] = prefix[j]

    return max_sum if max_sum is not None else 0
