def count_key_changes(s: str) -> int:
    if not s:
        return 0

    def normalized_char(ch: str) -> str:
        # Treat characters as the same key if their lowercase are the same
        # This ensures that case changes do not count as key changes.
        return ch.lower()

    changes = 0
    prev = normalized_char(s[0])

    for i in range(1, len(s)):
        cur = normalized_char(s[i])
        if cur != prev:
            changes += 1
            prev = cur
        else:
            # same key, no change; keep prev as is
            pass

    return changes

