        lines = 1
        current_line_width = 0
        for i in range(N):
            w = L[i]
            if current_line_width == 0:
                # start of a new line with the word
                if w > W:
                    return False
                current_line_width = w
            else:
                # try to place with a space before it
                if current_line_width + 1 + w <= W:
                    current_line_width += 1 + w
                else:
                    # place on next line
                    lines += 1
                    if lines > M:
                        return False
                    if w > W:
                        return False
                    current_line_width = w
        return True

    # Binary search on W
    lo = max(L)  # at least widest word
    hi = sum(L) + (N - 1)  # all words on one line with single spaces
    # Use while lo < hi
    while lo < hi:
        mid = (lo + hi) // 2
        if can_fit(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

