def median_uniqueness_array(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    median_rank = (total_subarrays + 1) // 2

    def count_at_most(k):
        freq = {}
        left = 0
        distinct = 0
        count = 0

        for right, x in enumerate(nums):
            freq[x] = freq.get(x, 0) + 1
            if freq[x] == 1:
                distinct += 1

            while distinct > k:
                y = nums[left]
                freq[y] -= 1
                if freq[y] == 0:
                    del freq[y]
                    distinct -= 1
                left += 1

            count += right - left + 1

        return count

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= median_rank:
            hi = mid
        else:
            lo = mid + 1

    return lo
