        dims.add((a, b))
        dims.add((b, a))
        tile_dims.append(list(dims))

    grid_size = H * W
    if grid_size == 0:
        print("No")
        return

    # We will perform backtracking with a bitset for used tiles
    used = [False] * N
    # Represent grid as a 2D array of booleans
    grid = [[False] * W for _ in range(H)]

    # Helper to find first empty cell (r,c)
    def first_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return None

    # Try to place a tile at position (r,c) with given height, width
    def can_place_at(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for rr in range(r, r + h):
            for cc in range(c, c + w):
                if grid[rr][cc]:
                    return False
        return True

    def place(r, c, h, w, val):
        for rr in range(r, r + h):
            for cc in range(c, c + w):
                grid[rr][cc] = val

    # Backtracking search
    # We also prune by remaining uncovered cells vs total area of remaining tiles
    # Compute for each tile its current possible area (h*w) depending on orientation
    # We'll just count total free cells and potential max area; simple prune: if
    # sum of areas of all unused tiles < free_cells -> fail; similarly min areas could overshoot, but complex.
    areas = []
    for a, b in tiles:
        areas.append(a * b)

    def remaining_free_cells():
        cnt = 0
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    cnt += 1
        return cnt

    # Precompute for speed: for each tile index, all (h,w) options
    tile_options = tile_dims

    # Main recursive function
    def dfs(placed_count):
        empty = first_empty()
        if empty is None:
            # All cells filled
            print("Yes")
            return True
        r, c = empty

        # Quick bound: compute free cells and max possible fill with remaining tiles
        free = remaining_free_cells()
        max_possible = 0
        for i in range(N):
            if not used[i]:
                # max area among its orientations
                max_area = max(h * w for h, w in tile_options[i])
                max_possible += max_area
        if max_possible < free:
            return False  # cannot fill all cells

        # Try each unused tile in any orientation that fits at (r,c)
        for i in range(N):
            if used[i]:
                continue
            used[i] = True
            for h, w in tile_options[i]:
                if can_place_at(r, c, h, w):
                    place(r, c, h, w, True)
                    if dfs(placed_count + 1):
                        return True
                    place(r, c, h, w, False)
            used[i] = False
        return False

    ok = dfs(0)
    if not ok:
