    idx = 3
    for _ in range(N):
        a = int(input_data[idx])
        b = int(input_data[idx+1])
        tiles.append((a, b))
        idx += 2

    # grid represented as a bitmask of size H*W
    # cells are (r, c), index = r * W + c

    memo = {}

    def can_fill(mask, tile_used_mask):
        if mask == (1 << (H * W)) - 1:
            return True
        if (mask, tile_used_mask) in memo:
            return memo[(mask, tile_used_mask)]

        # Find first empty cell
        first_empty = 0
        for i in range(H * W):
            if not (mask & (1 << i)):
                first_empty = i
                break

        r, c = divmod(first_empty, W)

        # Try all unused tiles
        for i in range(N):
            if not (tile_used_mask & (1 << i)):
                a, b = tiles[i]
                # Try two orientations (a, b) and (b, a)
                for h_size, w_size in set([(a, b), (b, a)]):
                    if r + h_size <= H and c + w_size <= W:
                        # Check if all cells for this tile are empty
                        can_place = True
                        new_mask = mask
                        for dr in range(h_size):
                            for dc in range(w_size):
                                pos = (r + dr) * W + (c + dc)
                                if mask & (1 << pos):
                                    can_place = False
                                    break
                                new_mask |= (1 << pos)
                            if not can_place: break

                        if can_place:
                            if can_fill(new_mask, tile_used_mask | (1 << i)):
                                memo[(mask, tile_used_mask)] = True
                                return True

        memo[(mask, tile_used_mask)] = False
        return False

    if can_fill(0, 0):
        print("Yes")
    else:
        print("No")

