    grid = [[False for _ in range(W)] for _ in range(H)]

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def set_tile(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack(tile_idx_mask):
        # Find the first empty cell
        r, c = -1, -1
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        # If no empty cell is found, all cells are covered
        if r == -1:
            return True

        # Try placing each unused tile
        for i in range(N):
            if not (tile_idx_mask & (1 << i)):
                # Try both orientations
                for h, w in [(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])]:
                    if can_place(r, c, h, w):
                        set_tile(r, c, h, w, True)
                        if backtrack(tile_idx_mask | (1 << i)):
                            return True
                        set_tile(r, c, h, w, False)
                    # If it's a square tile, don't try the rotated version
                    if tiles[i][0] == tiles[i][1]:
                        break
        return False

    if backtrack(0):
        print("Yes")
    else:
        print("No")

