import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    N, H, W = map(int, input_data[:3])
    tiles = []
    idx = 3
    for _ in range(N):
        a, b = int(input_data[idx]), int(input_data[idx+1])
        idx += 2
        tiles.append((a, b))

    grid = [[0] * W for _ in range(H)]
    used = [False] * N

    def can_place(x, y, w, h):
        if x + w > H or y + h > W:
            return False
        for i in range(x, x + w):
            for j in range(y, y + h):
                if grid[i][j] != 0:
                    return False
        return True

    def place(x, y, w, h, tile_id):
        for i in range(x, x + w):
            for j in range(y, y + h):
                grid[i][j] = tile_id

    def remove(x, y, w, h):
        for i in range(x, x + w):
            for j in range(y, y + h):
                grid[i][j] = 0

    # Find first empty cell
    def find_empty():
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    return i, j
        return None

    def backtrack():
        cell = find_empty()
        if cell is None:
            return True
        x, y = cell
        for t_idx in range(N):
            if used[t_idx]:
                continue
            a, b = tiles[t_idx]
            for w, h in [(a, b), (b, a)]:
                if can_place(x, y, w, h):
                    place(x, y, w, h, t_idx + 1)
                    used[t_idx] = True
                    if backtrack():
                        return True
                    used[t_idx] = False
                    remove(x, y, w, h)
        return False

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
