def find_repeating_and_missing(grid):
    """
    Given an n x n grid containing numbers 1..n^2 with exactly one number missing (b)
    and exactly one number repeating (a), return [a, b].
    """
    n = len(grid)
    # Flatten and count occurrences
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1

    a = b = None
    # a is the number with count 2, b is the number with count 0 (missing)
    # Build set of all numbers 1..n^2
    all_numbers = set(range(1, n * n + 1))

    for num, c in counts.items():
        if c == 2:
            a = num

    present = set(counts.keys())
    missing = all_numbers - present
    if missing:
        b = missing.pop()

    return [a, b]

