def can_traverse_all_pairs(nums):
    from math import gcd
    n = len(nums)
    # Build graph edges where gcd > 1
    # Use union-find (disjoint set) to determine connectivity
    parent = list(range(n))
    rank = [0]*n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[rb] < rank[ra]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    # To avoid O(n^2) checks, factorization approach:
    # Map value -> indices with that value
    max_val = max(nums) if nums else 0
    # Sieve smallest prime factor up to max_val
    spf = list(range(max_val+1))
    for i in range(2, int(max_val**0.5)+1):
        if spf[i] == i:
            step = i
            start = i*i
            for x in range(start, max_val+1, step):
                if spf[x] == x:
                    spf[x] = i

    from collections import defaultdict
    prime_to_indices = defaultdict(list)

    def factorize(x):
        res = set()
        while x > 1:
            p = spf[x]
            res.add(p)
            while x % p == 0:
                x //= p
        return res

    # Build groups by primes and union all indices sharing a common prime divisor
    for idx, val in enumerate(nums):
        primes = factorize(val)
        for p in primes:
            prime_to_indices[p].append(idx)

    # Union all indices that share a common prime factor
    for indices in prime_to_indices.values():
        if not indices:
            continue
        root = indices[0]
        for idx in indices[1:]:
            union(root, idx)

    # Check if all indices with gcd>1 connectivity forms a single component
    # If any two indices belong to different components, there exists pair not connected
    # But problem requires connectivity for all pairs i<j, i.e., overall graph connected.
    # If there is at least one edge (gcd>1) component connectivity may still be partial.
    # We need the entire graph to be connected considering only edges gcd>1.
    # So verify all indices share same root
    base = find(0)
    for i in range(1, n):
        if find(i) != base:
            return False
    return True

