def canTraverseAllPairs(nums: list[int]) -> bool:
    if len(nums) == 1:
        return True

    n = len(nums)
    # If there's a 1 in the list, it cannot be connected to anything else
    # unless it's the only element (handled above).
    if 1 in nums:
        return False

    # Disjoint Set Union (DSU) to group indices
    parent = list(range(n))
    size = [1] * n
    num_components = n

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        nonlocal num_components
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if size[root_i] < size[root_j]:
                root_i, root_j = root_j, root_i
            parent[root_j] = root_i
            size[root_i] += size[root_j]
            num_components -= 1

    # Map each prime factor to the first index in nums that contains it
    prime_to_first_index = {}

    max_val = max(nums)
    # Precompute smallest prime factor (SPF) for factorization up to max_val
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    for idx, val in enumerate(nums):
        temp = val
        while temp > 1:
            p = spf[temp]
            if p in prime_to_first_index:
                union(idx, prime_to_first_index[p])
            else:
                prime_to_first_index[p] = idx

            # Remove all instances of this prime factor
            while temp % p == 0:
                temp //= p

    return num_components == 1
