from typing import List

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n <= 1:
        return True
    if any(x == 1 for x in nums):
        return False

    max_val = max(nums)
    # smallest prime factor sieve
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:          # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    dsu = DSU(n)
    prime_to_idx = {}

    for i, num in enumerate(nums):
        temp = num
        prev = 0
        while temp > 1:
            p = spf[temp]
            if p != prev:        # distinct prime factor
                if p in prime_to_idx:
                    dsu.union(i, prime_to_idx[p])
                else:
                    prime_to_idx[p] = i
                prev = p
            temp //= p

    # check connectivity
    root = dsu.find(0)
    return all(dsu.find(i) == root for i in range(1, n))
