import sys

def solve() -> None:
    data = sys.stdin.read().split()
    it = iter(data)
    H = int(next(it))
    W = int(next(it))
    N = int(next(it))
    T = next(it)                     # move string
    grid = [next(it) for _ in range(H)]

    # land[i][j] == True means cell (i, j) is land
    land = [[c == '.' for c in row] for row in grid]

    # current set of possible positions after processing some moves
    cur = [row[:] for row in land]   # copy of land grid

    for ch in T:
        nxt = [[False] * W for _ in range(H)]
        if ch == 'L':
            for i in range(H):
                cur_row = cur[i]
                nxt_row = nxt[i]
                # j from 1 to W-1 because only those can move left
                for j in range(1, W):
                    if cur_row[j] and land[i][j-1]:
                        nxt_row[j-1] = True
        elif ch == 'R':
            for i in range(H):
                cur_row = cur[i]
                nxt_row = nxt[i]
                # j from 0 to W-2 because only those can move right
                for j in range(W-1):
                    if cur_row[j] and land[i][j+1]:
                        nxt_row[j+1] = True
        elif ch == 'U':
            for i in range(1, H):
                cur_row = cur[i]
                nxt_row = nxt[i-1]
                for j in range(W):
                    if cur_row[j] and land[i-1][j]:
                        nxt_row[j] = True
        else:  # 'D'
            for i in range(H-1):
                cur_row = cur[i]
                nxt_row = nxt[i+1]
                for j in range(W):
                    if cur_row[j] and land[i+1][j]:
                        nxt_row[j] = True
        cur = nxt

    # count True cells in the final grid
    ans = sum(sum(row) for row in cur)
    print(ans)

if __name__ == "__main__":
    solve()
```

