def max_jumps(nums, target):
    n = len(nums)
    # dp[i] = maximum jumps to reach index i from 0, or -inf if unreachable
    dp = [-10**9] * n
    dp[0] = 0
    for i in range(n):
        if dp[i] < 0:
            continue
        for j in range(i + 1, n):
            diff = nums[j] - nums[i]
            if -target <= diff <= target:
                if dp[i] + 1 > dp[j]:
                    dp[j] = dp[i] + 1
    return dp[n - 1] if dp[n - 1] >= 0 else -1

